import { useState, useCallback } from 'react';
import QUESTIONS from '../question.jsx'; 
import QuestionTimer from './QuestionTimer.jsx';
import quizCompleteImg from '../assets/quiz-complete.png';

export default function Quiz() {
    const [userAnswers, setUserAnswers] = useState([]); 
    const activeQuestionIndex = userAnswers.length; 
    const quizIsComplete = activeQuestionIndex === QUESTIONS.length;

    // 如果测验完成，就直接渲染完成的 UI，不执行后续的逻辑
    if (quizIsComplete) {
        return (
            <div id="summary">
                <img src={quizCompleteImg} alt="Quiz complete"/>
                <h2>Quiz Completed!</h2>
            </div>
        );
    }

    // 确保在测验未完成的情况下，这里的代码才会执行
    let shuffledAnswers = [...QUESTIONS[activeQuestionIndex].answers];
    shuffledAnswers.sort(() => Math.random() - 0.5);

    /*
        这段代码的作用是创建了一个优化后的回调函数handleSelectAnswer，
        当调用它时会将传入的参数添加到用户答案数组中，
        并且这个回调函数只会在组件首次渲染时创建一次，以后不会重新创建
    */
    const handleSelectAnswer = useCallback(function handleSelectAnswer(selectedAnswer) {
        setUserAnswers((prevUserAnswers) => {
            return [...prevUserAnswers, selectedAnswer];
        });
    }, []);

    /*
        这段代码的作用是创建了一个优化后的回调函数handleSkipAnswer，
        当调用它时会执行handleSelectAnswer(null)，
        并且只有在handleSelectAnswer函数发生变化时才会重新创建这个回调函数
    */
    const handleSkipAnswer = useCallback(() => handleSelectAnswer(null), [handleSelectAnswer]);

    return (
        <div id="quiz">
            <div id = "question">
                <QuestionTimer key = {activeQuestionIndex} timeout={10000} onTimeout={handleSkipAnswer}/>
                <h2>{QUESTIONS[activeQuestionIndex].text}</h2>
                <ul id="answers">
                    {shuffledAnswers.map((answer) => (
                        <li key={answer} className="answer">
                            <button onClick={() => handleSelectAnswer(answer)}>{answer}</button>
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
}
